import "./progress.css";

import type { ComponentProps, CSSProperties } from "react";
import { cx } from "./cx";

export type ProgressProps = ComponentProps<"progress">;
export type MeterProps = ComponentProps<"meter">;

function amountOf(
  value: string | number | readonly string[] | undefined,
  max: string | number | undefined,
) {
  if (value === undefined || value === "") return undefined;
  const next = Number(value);
  const top = Number(max ?? 1);
  if (!Number.isFinite(next) || !Number.isFinite(top) || top === 0) {
    return undefined;
  }
  return Math.min(1, Math.max(0, next / top));
}

export function Progress({
  className,
  value,
  max,
  style,
  ...rest
}: ProgressProps) {
  const amount = amountOf(value, max);
  return (
    <progress
      {...rest}
      value={value}
      max={max}
      className={cx("ns-progress", className)}
      style={
        {
          ...style,
          ...(amount == null ? {} : { "--ns-progress": String(amount) }),
        } as CSSProperties
      }
    />
  );
}

export function Meter({ className, value, min, max, style, ...rest }: MeterProps) {
  const start = Number(min ?? 0);
  const top = Number(max ?? 1);
  const span = top - start;
  const filled =
    value === undefined || value === "" || !Number.isFinite(span) || span === 0
      ? undefined
      : Math.min(1, Math.max(0, (Number(value) - start) / span));

  return (
    <meter
      {...rest}
      value={value}
      min={min}
      max={max}
      className={cx("ns-meter", className)}
      style={
        {
          ...style,
          ...(filled == null ? {} : { "--ns-meter": String(filled) }),
        } as CSSProperties
      }
    />
  );
}

@layer components {
  .ns-progress,
  .ns-meter {
    -webkit-appearance: none;
    appearance: none;
    display: block;
    box-sizing: border-box;
    width: 100%;
    height: var(--space-4, 0.49rem);
    margin: 0;
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: var(--radius, 0.4rem);
    --ns-amt: var(--ns-progress, var(--ns-meter, 0));
    --ns-cap: var(--space-4, 0.49rem);
    background-color: var(--bg-well, #e8e6e4);
    background-image:
      radial-gradient(circle closest-side, var(--ink, #111) 99%, transparent),
      linear-gradient(var(--ink, #111), var(--ink, #111));
    background-size:
      var(--ns-cap) var(--ns-cap),
      max(0%, calc(var(--ns-amt) * 100% - var(--ns-cap) / 2)) 100%;
    background-position:
      calc(var(--ns-amt) * 100% - var(--ns-cap)) 50%,
      0 0;
    background-repeat: no-repeat;
    background-clip: padding-box;
    box-shadow: inset 0 1px 0
      color-mix(in srgb, var(--shade, oklch(0 0 0 / 28%)) 55%, transparent);
    overflow: hidden;
  }

  .ns-progress::-webkit-progress-bar,
  .ns-progress::-webkit-progress-value,
  .ns-progress::-moz-progress-bar,
  .ns-meter::-webkit-meter-bar,
  .ns-meter::-webkit-meter-inner-element,
  .ns-meter::-webkit-meter-optimum-value,
  .ns-meter::-webkit-meter-suboptimum-value,
  .ns-meter::-webkit-meter-even-less-good-value,
  .ns-meter::-moz-meter-bar {
    background: transparent;
    border: 0;
    box-shadow: none;
  }

  .ns-progress:indeterminate {
    background-color: var(--bg-well, #e8e6e4);
    background-image: linear-gradient(
      90deg,
      transparent 0%,
      var(--ink, #111) 42%,
      var(--ink, #111) 58%,
      transparent 100%
    );
    background-size: 38% 100%;
    animation: ns-progress-indeterminate 1.2s
      var(--ease, cubic-bezier(0.22, 1, 0.36, 1)) infinite;
  }

  @keyframes ns-progress-indeterminate {
    0% {
      background-position: -40% 0;
    }
    100% {
      background-position: 140% 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-progress:indeterminate {
      animation: none;
      background-position: 50% 0;
    }
  }
}
